    fn prepared_naabu_work_plan_for_target(
        fixture: &Fixture,
        target: &str,
        resolved_addresses: Vec<std::net::IpAddr>,
    ) -> (String, ScanPlan, ResolvedExternalPlan, NaabuWorkPlanV1) {
        prepared_naabu_work_plan_for_target_and_ports(
            fixture,
            target,
            resolved_addresses,
            [443].into_iter().collect(),
        )
    }

    fn prepared_naabu_work_plan_for_target_and_ports(
        fixture: &Fixture,
        target: &str,
        resolved_addresses: Vec<std::net::IpAddr>,
        ports: BTreeSet<u16>,
    ) -> (String, ScanPlan, ResolvedExternalPlan, NaabuWorkPlanV1) {
        let created = fixture.create();
        let asset_id = approve_direct_external_target(
            fixture,
            &created.id,
            AssetKind::IpAddress,
            target,
            ScanPermission::LowImpactExternalConnection,
            crate::external_scope::TransportProtocol::Tcp,
            true,
        );
        let mut approved = fixture.service().show_case(&created.id).unwrap();
        let expanded_ports = ports.len() > 1;
        let external = approved
            .scope_grants
            .iter_mut()
            .find(|grant| grant.asset_id == asset_id)
            .and_then(|grant| grant.external_scope.as_mut())
            .expect("approved direct external scope");
        external.ports = ports;
        if expanded_ports {
            external.rate_policy = crate::external_scope::RatePolicy {
                requests_per_second: 25,
                concurrency: 10,
                timeout_seconds: 3,
            };
        }
        fixture
            .storage
            .save_case(&mut approved, "test.direct_external_ports_expanded")
            .unwrap();
        let scan_plan = fixture
            .service()
            .plan_scan_for_execution(
                &created.id,
                ScanPlanRequest {
                    engine_ids: vec![NAABU_ENGINE_ID.into()],
                },
            )
            .unwrap();
        let execution = scan_plan
            .executable
            .iter()
            .find(|execution| execution.manifest.id == NAABU_ENGINE_ID)
            .unwrap();
        let external = execution.scope_grants[0].external_scope.as_ref().unwrap();
        let frozen_at = Utc::now();
        let resolved = freeze_external_plan(external, resolved_addresses, frozen_at).unwrap();
        let identity = NaabuWorkPlanIdentity::new(
            &created.id,
            &execution.scan_run_id,
            &execution.engine_run_id,
            frozen_at,
        );
        let work_plan =
            build_naabu_work_plan(identity, std::slice::from_ref(&resolved), None).unwrap();
        (created.id, scan_plan, resolved, work_plan)
    }

    fn naabu_attempt_request(
        plan: &NaabuWorkPlanV1,
        execution_attempt: u32,
        requested_unit_ids: Vec<String>,
    ) -> NaabuAttemptRequest {
        let selected = requested_unit_ids.iter().cloned().collect::<BTreeSet<_>>();
        let launcher = plan
            .launcher_plan_v3(execution_attempt, Some(&selected))
            .expect("launcher plan fixture");
        NaabuAttemptRequest {
            schema_version: NAABU_ATTEMPT_REQUEST_SCHEMA_VERSION,
            execution_attempt,
            requested_unit_ids,
            launcher_plan_sha256: sha256_bytes(
                &serde_json::to_vec(&launcher).expect("launcher plan JSON"),
            ),
        }
    }

    fn normalized_complete_naabu_result(
        plan: &NaabuWorkPlanV1,
        request: &NaabuAttemptRequest,
    ) -> NaabuAttemptResult {
        let empty_sha256 = "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855";
        let work_units_by_id = plan
            .work_units
            .iter()
            .map(|unit| (unit.unit_id.as_str(), unit))
            .collect::<BTreeMap<_, _>>();
        let mut bindings = Vec::new();
        let mut work_units = Vec::new();
        for (ordinal, unit_id) in request.requested_unit_ids.iter().enumerate() {
            let unit = work_units_by_id[unit_id.as_str()];
            let identity = FinalArtifactIdentity {
                engine_run_id: plan.identity.engine_run_id.clone(),
                unit_id: unit.unit_id.clone(),
                scope_sha256: unit.scope_sha256.clone(),
                attempt: request.execution_attempt,
                relative_path: format!(
                    "attempt-{}/unit-{ordinal}.jsonl",
                    request.execution_attempt
                ),
                sha256: empty_sha256.into(),
                byte_length: 0,
            };
            bindings.push(crate::execution_coverage::ValidatedArtifactBinding {
                raw_artifact_id: format!(
                    "raw-naabu-complete-{}-{ordinal}",
                    request.execution_attempt
                ),
                identity: identity.clone(),
            });
            work_units.push(crate::execution_coverage::WorkUnitCoverage {
                unit_id: unit.unit_id.clone(),
                scope_sha256: unit.scope_sha256.clone(),
                outcome: WorkUnitOutcome::TestedComplete,
                attempts: vec![crate::execution_coverage::WorkUnitAttempt {
                    attempt: request.execution_attempt,
                    outcome: WorkUnitOutcome::TestedComplete,
                    incomplete_reason: None,
                    final_artifact: Some(identity),
                }],
            });
        }
        let requested = work_units.len();
        NaabuAttemptResult {
            schema_version: NAABU_ATTEMPT_RESULT_SCHEMA_VERSION,
            execution_attempt: request.execution_attempt,
            journal_raw_artifact_id: format!(
                "raw-naabu-complete-journal-{}",
                request.execution_attempt
            ),
            coverage: crate::execution_coverage::ValidatedExecutionCoverage {
                schema_version: crate::execution_coverage::LAUNCHER_V2_JOURNAL_SCHEMA_VERSION,
                engine_run_id: plan.identity.engine_run_id.clone(),
                execution_attempt: request.execution_attempt,
                recovered_trailing_record: false,
                validated_artifact_bindings: bindings,
                unreferenced_final_artifacts: Vec::new(),
                work_units,
                summary: crate::execution_coverage::ExecutionCoverageSummary {
                    requested,
                    tested_complete: requested,
                    tested_partial: 0,
                    failed: 0,
                    timed_out: 0,
                    cancelled: 0,
                    not_tested: 0,
                    partial: false,
                    has_usable_results: true,
                },
            },
            normalization_complete: true,
        }
    }

    struct PreparedNaabuAttemptResult {
        case_id: String,
        scan_run_id: String,
        engine_run_id: String,
        plan: NaabuWorkPlanV1,
        request: NaabuAttemptRequest,
        result: NaabuAttemptResult,
    }

    fn prepared_naabu_attempt_result(
        fixture: &Fixture,
        outcome: WorkUnitOutcome,
        normalization_complete: bool,
    ) -> PreparedNaabuAttemptResult {
        prepared_naabu_attempt_result_with_suffix(fixture, outcome, normalization_complete, &[])
    }

    fn prepared_naabu_attempt_result_with_suffix(
        fixture: &Fixture,
        outcome: WorkUnitOutcome,
        normalization_complete: bool,
        final_suffix: &[u8],
    ) -> PreparedNaabuAttemptResult {
        prepared_naabu_attempt_result_with_target(
            fixture,
            outcome,
            normalization_complete,
            final_suffix,
            "198.51.100.0/30",
            vec![
                "198.51.100.1".parse().unwrap(),
                "198.51.100.2".parse().unwrap(),
            ],
        )
    }

    fn prepared_naabu_attempt_result_with_target(
        fixture: &Fixture,
        outcome: WorkUnitOutcome,
        normalization_complete: bool,
        final_suffix: &[u8],
        target: &str,
        resolved_addresses: Vec<std::net::IpAddr>,
    ) -> PreparedNaabuAttemptResult {
        assert!(matches!(
            outcome,
            WorkUnitOutcome::TestedComplete | WorkUnitOutcome::TestedPartial
        ));
        let (case_id, scan_plan, _, plan) =
            prepared_naabu_work_plan_for_target(fixture, target, resolved_addresses);
        let execution = scan_plan.executable.first().unwrap();
        let unit = plan.work_units.first().unwrap();
        let request = naabu_attempt_request(&plan, 1, vec![unit.unit_id.clone()]);
        fixture
            .service()
            .persist_naabu_attempt_request(
                &case_id,
                &execution.scan_run_id,
                &execution.engine_run_id,
                &plan,
                &request,
            )
            .unwrap();

        let grant = &plan.frozen_grants[unit.grant_index as usize];
        let mut final_bytes = serde_json::to_vec(&serde_json::json!({
            "host": grant.addresses[unit.address_start as usize].to_string(),
            "port": grant.ports[unit.port_start as usize],
            "protocol": "tcp",
            "asset_id": grant.asset_id,
        }))
        .unwrap();
        final_bytes.push(b'\n');
        final_bytes.extend_from_slice(final_suffix);
        let final_relative = "launcher-v2/units/unit-000000/attempt-1.jsonl";
        let final_identity = FinalArtifactIdentity {
            engine_run_id: execution.engine_run_id.clone(),
            unit_id: unit.unit_id.clone(),
            scope_sha256: unit.scope_sha256.clone(),
            attempt: 1,
            relative_path: final_relative.into(),
            sha256: sha256_bytes(&final_bytes),
            byte_length: final_bytes.len() as u64,
        };
        let requested = vec![RequestedWorkUnit {
            unit_id: unit.unit_id.clone(),
            scope_sha256: unit.scope_sha256.clone(),
        }];
        let mut journal = serde_json::to_vec(&serde_json::json!({
            "record_type": "header",
            "schema_version": 2,
            "engine_run_id": execution.engine_run_id,
            "execution_attempt": 1,
            "requested_work_units": requested,
        }))
        .unwrap();
        journal.push(b'\n');
        journal.extend_from_slice(
            &serde_json::to_vec(&serde_json::json!({
                "record_type": "attempt_finished",
                "unit_id": unit.unit_id,
                "scope_sha256": unit.scope_sha256,
                "attempt": 1,
                "outcome": outcome,
                "incomplete_reason": (outcome == WorkUnitOutcome::TestedPartial)
                    .then_some(IncompleteReason::Failed),
                "final_artifact": final_identity,
            }))
            .unwrap(),
        );
        journal.push(b'\n');

        let artifact_prefix = format!(
            "{}/{}/{}/attempt-1/output",
            case_id, execution.scan_run_id, execution.engine_run_id
        );
        let journal_raw = RawArtifact {
            id: "raw-naabu-journal-1".into(),
            case_id: case_id.clone(),
            run_id: execution.scan_run_id.clone(),
            engine_run_id: execution.engine_run_id.clone(),
            relative_path: format!("{artifact_prefix}/launcher-v2/journal.jsonl"),
            media_type: "application/x-ndjson".into(),
            sha256: sha256_bytes(&journal),
            byte_length: journal.len() as u64,
            created_at: Utc::now(),
            contains_sensitive_data: true,
        };
        let final_raw = RawArtifact {
            id: "raw-naabu-final-1".into(),
            case_id: case_id.clone(),
            run_id: execution.scan_run_id.clone(),
            engine_run_id: execution.engine_run_id.clone(),
            relative_path: format!("{artifact_prefix}/{final_relative}"),
            media_type: "application/x-ndjson".into(),
            sha256: sha256_bytes(&final_bytes),
            byte_length: final_bytes.len() as u64,
            created_at: Utc::now(),
            contains_sensitive_data: true,
        };
        let artifact_root = fixture.directory.path().join("artifacts");
        for (artifact, bytes) in [
            (&journal_raw, journal.as_slice()),
            (&final_raw, final_bytes.as_slice()),
        ] {
            let path = artifact_root.join(&artifact.relative_path);
            fs::create_dir_all(path.parent().unwrap()).unwrap();
            fs::write(path, bytes).unwrap();
        }
        let observed = vec![HostObservedFinalArtifact {
            raw_artifact_id: final_raw.id.clone(),
            relative_path: final_relative.into(),
            sha256: final_raw.sha256.clone(),
            byte_length: final_raw.byte_length,
        }];
        let coverage =
            parse_launcher_v2_journal(&journal, &execution.engine_run_id, 1, &requested, &observed)
                .unwrap();
        let result = NaabuAttemptResult {
            schema_version: NAABU_ATTEMPT_RESULT_SCHEMA_VERSION,
            execution_attempt: 1,
            journal_raw_artifact_id: journal_raw.id.clone(),
            coverage,
            normalization_complete,
        };

        let mut case = fixture.service().show_case(&case_id).unwrap();
        case.raw_artifacts.push(journal_raw);
        case.raw_artifacts.push(final_raw);
        let engine_run = case
            .scan_runs
            .iter_mut()
            .find(|run| run.id == execution.scan_run_id)
            .unwrap()
            .engine_runs
            .iter_mut()
            .find(|engine_run| engine_run.id == execution.engine_run_id)
            .unwrap();
        engine_run.raw_artifact_ids =
            vec!["raw-naabu-final-1".into(), "raw-naabu-journal-1".into()];
        fixture
            .storage
            .save_case(&mut case, "test.naabu_launcher_v2_artifacts")
            .unwrap();

        PreparedNaabuAttemptResult {
            case_id,
            scan_run_id: execution.scan_run_id.clone(),
            engine_run_id: execution.engine_run_id.clone(),
            plan,
            request,
            result,
        }
    }

