    #[test]
    fn guided_internal_network_journey_reopens_and_exports_the_same_durable_report() {
        let fixture = Fixture::with_engines(current_launcher_engine_registry());
        let created = fixture.create_with_intent(Some(AssessmentIntent::InternalItEnvironment));
        let target = "192.168.50.0/24";
        let (mut discovered, asset_id) =
            fixture.discovered_asset(&created.id, AssetKind::IpAddress);
        let asset = discovered
            .assets
            .iter_mut()
            .find(|asset| asset.id == asset_id)
            .expect("guided internal target");
        asset.name = target.into();
        asset.identifiers = vec![AssetIdentifier {
            namespace: "external_target".into(),
            value: target.into(),
        }];
        asset.internet_exposed = Some(false);
        fixture
            .storage
            .save_case(&mut discovered, "test.guided_internal_target_attributed")
            .unwrap();

        let ports = [
            21, 22, 25, 53, 80, 110, 139, 143, 443, 445, 465, 587, 993, 995, 3_306, 3_389, 5_432,
            6_379, 8_080, 8_443, 9_100,
        ]
        .into_iter()
        .collect::<BTreeSet<_>>();
        let confirmation = "I confirm this scan may connect to the selected internal network";
        let scan_plan = fixture
            .service()
            .authorize_and_persist_scan_before_execution_preflight(
                &created.id,
                vec![ScopeApprovalRequest {
                    asset_id: asset_id.clone(),
                    permissions: vec![ScanPermission::LowImpactExternalConnection],
                    confirmed_by: "Local user".into(),
                    expires_at: Some(Utc::now() + Duration::days(30)),
                    authorization_reference: Some(confirmation.into()),
                    notes: Some(confirmation.into()),
                    external_scope: Some(ExternalScopeRequest {
                        target: target.into(),
                        ports: ports.clone(),
                        protocol: crate::external_scope::TransportProtocol::Tcp,
                        activity: ExternalActivity::LowImpactExternal,
                        rate_policy: crate::external_scope::RatePolicy {
                            requests_per_second: 25,
                            concurrency: 10,
                            timeout_seconds: 3,
                        },
                        template_policy: crate::external_scope::TemplatePolicy::conservative(
                            "not_applicable",
                            vec![],
                        ),
                        asserted_authority: confirmation.into(),
                        allow_sensitive_networks: true,
                    }),
                }],
                ScanPlanRequest {
                    engine_ids: vec![NAABU_ENGINE_ID.into()],
                },
            )
            .expect("one Start saves the private target, limits, and scan");
        assert_eq!(scan_plan.executable.len(), 1);
        assert!(scan_plan.not_executed.is_empty());
        let execution = &scan_plan.executable[0];
        assert_eq!(execution.manifest.id, NAABU_ENGINE_ID);
        assert_eq!(execution.assets[0].id, asset_id);
        let frozen_at = Utc::now();
        let resolved_addresses = (1..=254)
            .map(|host| std::net::Ipv4Addr::new(192, 168, 50, host).into())
            .collect::<Vec<std::net::IpAddr>>();
        let resolved = freeze_external_plan(
            execution.scope_grants[0]
                .external_scope
                .as_ref()
                .expect("frozen internal scope"),
            resolved_addresses,
            frozen_at,
        )
        .expect("freeze exact internal addresses");
        let work_plan = build_naabu_work_plan(
            NaabuWorkPlanIdentity::new(
                &created.id,
                &execution.scan_run_id,
                &execution.engine_run_id,
                frozen_at,
            ),
            &[resolved],
            None,
        )
        .expect("build staged internal inventory");
        assert!(
            work_plan.work_units.iter().any(|unit| {
                unit.stage == crate::naabu_work_plan::NaabuWorkStage::QuickDiscovery
            })
        );
        assert!(
            work_plan.work_units.iter().any(|unit| {
                unit.stage == crate::naabu_work_plan::NaabuWorkStage::FullInventory
            })
        );
        assert_eq!(work_plan.frozen_grants[0].addresses.len(), 254);
        assert_eq!(
            work_plan.frozen_grants[0]
                .ports
                .iter()
                .copied()
                .collect::<BTreeSet<_>>(),
            ports
        );
        assert_eq!(
            work_plan
                .work_units
                .iter()
                .map(|unit| unit.endpoint_pair_count)
                .sum::<u64>(),
            254 * ports.len() as u64,
            "quick discovery plus inventory must retain every requested host/port pair exactly once"
        );
        let attempt = naabu_attempt_request(
            &work_plan,
            1,
            work_plan
                .work_units
                .iter()
                .map(|unit| unit.unit_id.clone())
                .collect(),
        );
        fixture
            .service()
            .persist_naabu_attempt_request(
                &created.id,
                &execution.scan_run_id,
                &execution.engine_run_id,
                &work_plan,
                &attempt,
            )
            .expect("persist exact internal work before its result");

        let result = normalized_complete_naabu_result(&work_plan, &attempt);
        let mut completed = fixture.service().show_case(&created.id).unwrap();
        let run = completed
            .scan_runs
            .iter_mut()
            .find(|run| run.id == execution.scan_run_id)
            .unwrap();
        run.completed_at = Some(Utc::now());
        let engine_run = run
            .engine_runs
            .iter_mut()
            .find(|engine_run| engine_run.id == execution.engine_run_id)
            .unwrap();
        engine_run.naabu_attempt_results.push(result);
        engine_run.status = EngineRunStatus::Completed;
        engine_run.progress_percent = 100;
        engine_run.phase = "completed".into();
        engine_run.finished_at = run.completed_at;
        completed.status = CaseStatus::ReadyForHandoff;
        completed.touch();
        fixture
            .storage
            .save_case(&mut completed, "test.guided_internal_scan_completed")
            .expect("save terminal internal result");

        let reopened_storage = Storage::open(fixture.directory.path().join("casework.db"))
            .expect("reopen durable case database");
        let reopened = reopened_storage
            .get_case(&created.id)
            .expect("reopen the same internal scan project");
        assert_eq!(
            reopened.assessment_intent,
            Some(AssessmentIntent::InternalItEnvironment)
        );
        let report = build_beginner_master_report(&reopened, &execution.scan_run_id)
            .expect("build beginner report from reopened internal scan");
        assert_eq!(report.state.summary, BeginnerReportSummary::Complete);
        assert_eq!(report.state.lifecycle, ReportLifecycle::Final);
        assert!(report.coverage_gaps.is_empty());
        assert_eq!(
            report.requested.stage.value,
            Some(crate::beginner_report::ReportScanStage::Inventory)
        );
        assert!(report.requested.automatic_reductions.is_empty());
        assert_eq!(
            report.requested.reductions_availability,
            crate::beginner_report::DataAvailability::Recorded
        );
        assert!(report.requested.limits.iter().any(|limit| {
            limit.name.ends_with("approved ports")
                && ports.iter().all(|port| {
                    limit
                        .value
                        .split(',')
                        .any(|value| value == port.to_string())
                })
        }));
        assert_eq!(
            report.actual.network_scopes.len(),
            work_plan.work_units.len()
        );
        assert!(report.actual.network_scopes.iter().all(|scope| {
            scope.target == target && scope.outcome == WorkUnitOutcome::TestedComplete
        }));

        let reopened_service = CaseService::new(
            &reopened_storage,
            &fixture.engines,
            &fixture.adapters,
            fixture.directory.path().join("artifacts"),
            fixture.directory.path().join("signing.key"),
        );
        let destination = fixture.directory.path().join("guided-internal-report.html");
        let exported = reopened_service
            .export_case(
                &created.id,
                &execution.scan_run_id,
                CaseExportFormat::Html,
                &destination,
                ExportOptions {
                    redaction: RedactionProfile::None,
                    include_raw_artifacts: false,
                    locale: crate::export::ReportLocale::En,
                },
            )
            .expect("export reopened internal beginner report");
        assert!(
            reopened_service
                .verify_stored_export(&created.id, &exported.id)
                .expect("verify stored internal HTML export")
                .valid
        );
        let html = fs::read_to_string(destination).expect("read exported internal HTML");
        for expected in [
            "Complete",
            "Final for this run",
            "192.168.50.0/24",
            "What was actually tested",
            "What was not tested",
            "What to do next",
            "do not establish certification",
            "Content-Security-Policy",
        ] {
            assert!(
                html.contains(expected),
                "missing readable report text: {expected}"
            );
        }
        assert!(!html.contains("<script"));
    }

    #[test]
    fn requested_network_stage_aggregates_all_saved_task_plans() {
        let fixture = Fixture::new();
        let (case_id, scan_plan, _, plan) = prepared_naabu_work_plan(&fixture);
        assert!(
            plan.work_units
                .iter()
                .any(|unit| unit.stage == crate::naabu_work_plan::NaabuWorkStage::FullInventory)
        );
        let execution = scan_plan
            .executable
            .iter()
            .find(|execution| execution.manifest.id == NAABU_ENGINE_ID)
            .unwrap();
        let request = naabu_attempt_request(
            &plan,
            1,
            plan.work_units
                .iter()
                .map(|unit| unit.unit_id.clone())
                .collect(),
        );
        fixture
            .service()
            .persist_naabu_attempt_request(
                &case_id,
                &execution.scan_run_id,
                &execution.engine_run_id,
                &plan,
                &request,
            )
            .unwrap();

        let mut case = fixture.service().show_case(&case_id).unwrap();
        let run = case
            .scan_runs
            .iter_mut()
            .find(|run| run.id == execution.scan_run_id)
            .unwrap();
        let mut corrupt_first = run.engine_runs[0].clone();
        corrupt_first.id = "000-corrupt-naabu-task".into();
        corrupt_first.naabu_attempt_requests.clear();
        corrupt_first.naabu_attempt_results.clear();
        corrupt_first
            .naabu_work_plan
            .as_mut()
            .unwrap()
            .identity
            .schema_version = u32::MAX;
        run.engine_runs.insert(0, corrupt_first);

        let report = build_beginner_master_report(&case, &execution.scan_run_id).unwrap();
        assert_eq!(
            report.requested.stage.value,
            Some(crate::beginner_report::ReportScanStage::Inventory),
            "a corrupt first sibling must not hide a later valid inventory plan"
        );
        assert_eq!(
            report.requested.stage.availability,
            crate::beginner_report::DataAvailability::Unavailable,
            "the report must also disclose that another sibling plan was unreadable"
        );
        assert!(
            report
                .requested
                .stage
                .explanation
                .contains("highest known stage")
        );
        assert_eq!(
            report.requested.reductions_availability,
            crate::beginner_report::DataAvailability::Unavailable
        );
    }

    #[test]
    fn naabu_retry_unions_same_run_finding_evidence_without_duplicates() {
        let fixture = Fixture::new();
        let prepared =
            prepared_naabu_attempt_result(&fixture, WorkUnitOutcome::TestedPartial, false);
        fixture
            .service()
            .persist_naabu_attempt_result(
                &prepared.case_id,
                &prepared.scan_run_id,
                &prepared.engine_run_id,
                &prepared.result,
            )
            .unwrap();
        let first = fixture
            .service()
            .adapt_and_persist_naabu_attempt(
                &prepared.case_id,
                &prepared.scan_run_id,
                &prepared.engine_run_id,
                1,
            )
            .unwrap();
        assert_eq!(first.findings.len(), 1);
        assert_eq!(first.findings[0].evidence.len(), 1);
        let first_evidence_id = first.findings[0].evidence[0].id.clone();
        let first_evidence_artifact = first.findings[0].evidence[0].artifact_id.clone();

        mark_naabu_attempt_clean_for_retry(&fixture, &prepared);
        let second_result =
            prepared_naabu_retry_result(&fixture, &prepared, 2, WorkUnitOutcome::TestedComplete);
        fixture
            .service()
            .persist_naabu_attempt_result(
                &prepared.case_id,
                &prepared.scan_run_id,
                &prepared.engine_run_id,
                &second_result,
            )
            .unwrap();
        let before_second = fixture.service().show_case(&prepared.case_id).unwrap();
        let events_before = fixture
            .storage
            .list_case_events(&prepared.case_id)
            .unwrap()
            .len();
        let merged = fixture
            .service()
            .adapt_and_persist_naabu_attempt(
                &prepared.case_id,
                &prepared.scan_run_id,
                &prepared.engine_run_id,
                2,
            )
            .expect("same fingerprint retry evidence is monotonic");

        assert_eq!(merged.storage_revision, before_second.storage_revision + 1);
        assert_eq!(merged.findings.len(), 1);
        assert_eq!(merged.finding_observations.len(), 1);
        assert_eq!(merged.findings[0].evidence.len(), 2);
        assert!(
            merged.findings[0]
                .evidence
                .iter()
                .any(|evidence| evidence.id == first_evidence_id
                    && evidence.artifact_id == first_evidence_artifact)
        );
        assert!(
            merged.findings[0]
                .evidence
                .iter()
                .any(|evidence| evidence.artifact_id == "raw-naabu-final-2")
        );
        assert_eq!(
            merged.finding_observations[0]
                .finding_snapshot
                .as_ref()
                .unwrap()
                .evidence
                .len(),
            2
        );
        assert!(merged.scan_runs[0].engine_runs[0].naabu_attempt_results[1].normalization_complete);
        let events = fixture.storage.list_case_events(&prepared.case_id).unwrap();
        assert_eq!(events.len(), events_before + 1);

        let replayed = fixture
            .service()
            .adapt_and_persist_naabu_attempt(
                &prepared.case_id,
                &prepared.scan_run_id,
                &prepared.engine_run_id,
                2,
            )
            .unwrap();
        assert_eq!(replayed.storage_revision, merged.storage_revision);
        assert_eq!(
            fixture
                .storage
                .list_case_events(&prepared.case_id)
                .unwrap()
                .len(),
            events.len()
        );
    }

    #[test]
    fn cumulative_complete_units_cannot_be_redispatched_but_partial_units_can() {
        let complete_fixture = Fixture::new();
        let complete = prepared_naabu_attempt_result(
            &complete_fixture,
            WorkUnitOutcome::TestedComplete,
            false,
        );
        complete_fixture
            .service()
            .persist_naabu_attempt_result(
                &complete.case_id,
                &complete.scan_run_id,
                &complete.engine_run_id,
                &complete.result,
            )
            .unwrap();
        mark_naabu_attempt_clean_for_retry(&complete_fixture, &complete);
        let completed_unit = complete.request.requested_unit_ids[0].clone();
        let retryable_sibling = complete.plan.work_units[1].unit_id.clone();
        let before_rejections = complete_fixture
            .service()
            .show_case(&complete.case_id)
            .unwrap();
        let events_before_rejections = complete_fixture
            .storage
            .list_case_events(&complete.case_id)
            .unwrap()
            .len();
        for requested in [
            vec![completed_unit.clone()],
            vec![completed_unit.clone(), retryable_sibling],
        ] {
            let second = naabu_attempt_request(&complete.plan, 2, requested);
            assert!(matches!(
                complete_fixture.service().persist_naabu_attempt_request(
                    &complete.case_id,
                    &complete.scan_run_id,
                    &complete.engine_run_id,
                    &complete.plan,
                    &second,
                ),
                Err(AppError::Conflict(_))
            ));
            assert_eq!(
                complete_fixture
                    .service()
                    .show_case(&complete.case_id)
                    .unwrap()
                    .storage_revision,
                before_rejections.storage_revision
            );
            assert_eq!(
                complete_fixture
                    .storage
                    .list_case_events(&complete.case_id)
                    .unwrap()
                    .len(),
                events_before_rejections
            );
        }
        assert_eq!(
            complete_fixture
                .service()
                .show_case(&complete.case_id)
                .unwrap()
                .scan_runs[0]
                .engine_runs[0]
                .naabu_attempt_requests,
            [complete.request]
        );

        let partial_fixture = Fixture::new();
        let partial =
            prepared_naabu_attempt_result(&partial_fixture, WorkUnitOutcome::TestedPartial, false);
        partial_fixture
            .service()
            .persist_naabu_attempt_result(
                &partial.case_id,
                &partial.scan_run_id,
                &partial.engine_run_id,
                &partial.result,
            )
            .unwrap();
        mark_naabu_attempt_clean_for_retry(&partial_fixture, &partial);
        let second =
            naabu_attempt_request(&partial.plan, 2, partial.request.requested_unit_ids.clone());
        let retried = partial_fixture
            .service()
            .persist_naabu_attempt_request(
                &partial.case_id,
                &partial.scan_run_id,
                &partial.engine_run_id,
                &partial.plan,
                &second,
            )
            .expect("tested-partial work remains retryable");
        assert_eq!(
            retried.scan_runs[0].engine_runs[0]
                .naabu_attempt_requests
                .len(),
            2
        );
    }

    #[test]
    fn late_complete_result_survives_an_already_committed_retry_request() {
        let fixture = Fixture::new();
        let prepared =
            prepared_naabu_attempt_result(&fixture, WorkUnitOutcome::TestedComplete, false);
        mark_naabu_attempt_clean_for_retry(&fixture, &prepared);
        let second = naabu_attempt_request(
            &prepared.plan,
            2,
            prepared.request.requested_unit_ids.clone(),
        );
        let after_retry_request = fixture
            .service()
            .persist_naabu_attempt_request(
                &prepared.case_id,
                &prepared.scan_run_id,
                &prepared.engine_run_id,
                &prepared.plan,
                &second,
            )
            .expect("retry may commit while the prior result is still in flight");
        assert_eq!(
            after_retry_request.scan_runs[0].engine_runs[0].naabu_attempt_requests,
            [prepared.request.clone(), second]
        );
        assert!(
            after_retry_request.scan_runs[0].engine_runs[0]
                .naabu_attempt_results
                .is_empty()
        );

        let events_before_result = fixture
            .storage
            .list_case_events(&prepared.case_id)
            .unwrap()
            .len();
        let persisted = fixture
            .service()
            .persist_naabu_attempt_result(
                &prepared.case_id,
                &prepared.scan_run_id,
                &prepared.engine_run_id,
                &prepared.result,
            )
            .expect("valid late evidence must remain durable regardless of race order");
        let engine_run = &persisted.scan_runs[0].engine_runs[0];
        assert_eq!(engine_run.naabu_attempt_results, [prepared.result]);
        let cumulative = reduce_naabu_attempt_coverage(
            engine_run.naabu_work_plan.as_ref().unwrap(),
            &engine_run.naabu_attempt_requests,
            &engine_run.naabu_attempt_results,
        )
        .unwrap();
        assert_eq!(cumulative.summary.tested_complete, 1);
        assert!(cumulative.retryable_unit_ids.iter().all(|unit_id| {
            !engine_run.naabu_attempt_requests[0]
                .requested_unit_ids
                .contains(unit_id)
        }));
        let events = fixture.storage.list_case_events(&prepared.case_id).unwrap();
        assert_eq!(events.len(), events_before_result + 1);
        assert_eq!(
            events.last().unwrap().event_type,
            "execution.naabu_attempt_result_persisted"
        );
    }

    fn naabu_planned_report(
        case_id: &str,
        execution: &PlannedEngineExecution,
        attempt: u32,
        launcher_plan_sha256: Option<String>,
    ) -> DurableExecutionReport {
        DurableExecutionReport {
            checkpoint: ExecutionCheckpoint {
                case_id: case_id.into(),
                scan_run_id: execution.scan_run_id.clone(),
                engine_run_id: execution.engine_run_id.clone(),
                engine_id: NAABU_ENGINE_ID.into(),
                attempt,
                stage: ExecutionStage::Planned,
                container_name: Some(
                    crate::container_runtime::planned_container_name(
                        NAABU_ENGINE_ID,
                        &execution.engine_run_id,
                        attempt,
                    )
                    .unwrap(),
                ),
                scope_sha256: Some("b".repeat(64)),
                launcher_plan_sha256,
                artifact_ids: Vec::new(),
                cleanup_completed: true,
                last_error: None,
                runtime_command_provenance: None,
                runtime_provider: None,
                managed_network: None,
            },
            runtime_preflight: None,
            cleanup: None,
            exit_code: None,
            raw_artifacts: Vec::new(),
            findings: Vec::new(),
            warnings: Vec::new(),
        }
    }

    fn append_planned_resume_sibling(
        case: &mut AssessmentCase,
        source_engine_index: usize,
        engine_id: &str,
    ) -> String {
        let scan_run = case.scan_runs.first_mut().unwrap();
        let mut sibling = scan_run.engine_runs[source_engine_index].clone();
        let sibling_id = new_id();
        sibling.id = sibling_id.clone();
        sibling.engine_id = engine_id.into();
        sibling.status = EngineRunStatus::Queued;
        sibling.progress_percent = 0;
        sibling.phase = "queued".into();
        sibling.started_at = None;
        sibling.finished_at = None;
        sibling.naabu_work_plan = None;
        sibling.naabu_attempt_requests.clear();
        sibling.naabu_attempt_results.clear();
        sibling.runtime_provider = None;
        sibling.runtime_version = None;
        sibling.runtime_security_options = None;
        sibling.exit_code = None;
        sibling.cleanup_removed = None;
        sibling.cleanup_detail = None;
        sibling.warnings.clear();
        sibling.raw_artifact_ids.clear();
        sibling.error_code = None;
        sibling.error_message = None;
        sibling.resume_token = Some(
            ExecutionCheckpoint {
                case_id: case.id.clone(),
                scan_run_id: scan_run.id.clone(),
                engine_run_id: sibling_id.clone(),
                engine_id: engine_id.into(),
                attempt: 1,
                stage: ExecutionStage::Planned,
                container_name: None,
                scope_sha256: None,
                launcher_plan_sha256: None,
                artifact_ids: Vec::new(),
                cleanup_completed: true,
                last_error: None,
                runtime_command_provenance: None,
                runtime_provider: None,
                managed_network: None,
            }
            .resume_token()
            .unwrap(),
        );
        scan_run.engine_runs.push(sibling);
        sibling_id
    }

    fn write_legacy_artifact_deletion_obligation(
        fixture: &Fixture,
        plan: &ArtifactDeletionPlan,
    ) -> PathBuf {
        let root = fixture
            .directory
            .path()
            .join("artifacts")
            .join(LEGACY_DELETION_OBLIGATION_DIRECTORY);
        fs::create_dir_all(&root).unwrap();
        let path = root.join(format!("{}.json", plan.case_id));
        fs::write(&path, serde_json::to_vec_pretty(plan).unwrap()).unwrap();
        path
    }

