    #[test]
    fn resume_identity_rejects_a_changed_active_execution_timeout() {
        let mut manifest = comparison_scope_manifest();
        manifest.execution = Some(EngineExecutionContract {
            resources: EngineExecutionResources {
                timeout_seconds: 7_200,
            },
            launcher_journal_version: None,
        });
        let engine_run = not_executed_run(
            "scan-1",
            "engine-run-1",
            &manifest.id,
            Vec::new(),
            ("fixture", "fixture"),
            Some(&manifest),
            Utc::now(),
        );
        assert_eq!(engine_run.execution_timeout_seconds, Some(7_200));
        validate_resume_manifest_identity(
            &engine_run,
            &manifest,
            ResumeManifestDriftAllowance::STRICT,
        )
        .expect("unchanged execution timeout remains resumable");

        manifest
            .execution
            .as_mut()
            .expect("execution contract")
            .resources
            .timeout_seconds = 7_201;
        let error = validate_resume_manifest_identity(
            &engine_run,
            &manifest,
            ResumeManifestDriftAllowance::STRICT,
        )
        .expect_err("catalog timeout drift must reject resume");
        assert!(error.to_string().contains("active execution deadline"));
    }

    #[test]
    fn unavailable_or_changed_framework_mapping_never_blocks_scanner_execution() {
        let (version, provenance, warning) = optional_control_mapping_identity_with(
            || {
                Err(AppError::NotAvailable(
                    "fixture mapping version secret".into(),
                ))
            },
            || Err(AppError::NotAvailable("fixture provenance secret".into())),
        );
        assert!(version.is_none());
        assert!(provenance.is_none());
        let warning = warning.expect("degraded mapping warning");
        assert_eq!(warning, CONTROL_MAPPING_UNAVAILABLE_WARNING);
        assert!(!warning.contains("secret"));
        assert!(warning.chars().count() <= 1_000);

        let manifest = comparison_scope_manifest();
        let mut engine_run = not_executed_run(
            "scan-1",
            "engine-run-1",
            &manifest.id,
            Vec::new(),
            ("fixture", "fixture"),
            Some(&manifest),
            Utc::now(),
        );
        engine_run.mapping_version = None;
        engine_run.mapping_provenance = None;
        validate_resume_manifest_identity(
            &engine_run,
            &manifest,
            ResumeManifestDriftAllowance::STRICT,
        )
        .expect("framework mapping is a reporting overlay, not an execution identity gate");
    }

    #[test]
    fn legacy_resume_identity_without_a_recorded_deadline_is_not_reexecution_compatible() {
        let mut manifest = comparison_scope_manifest();
        let engine_run = not_executed_run(
            "scan-1",
            "engine-run-1",
            &manifest.id,
            Vec::new(),
            ("fixture", "fixture"),
            Some(&manifest),
            Utc::now(),
        );
        let mut serialized = serde_json::to_value(&engine_run).expect("serialize engine run");
        serialized
            .as_object_mut()
            .expect("engine run object")
            .remove("execution_timeout_seconds");
        let legacy: EngineRun =
            serde_json::from_value(serialized).expect("legacy engine run remains readable");
        assert_eq!(legacy.execution_timeout_seconds, None);

        manifest.execution = Some(EngineExecutionContract {
            resources: EngineExecutionResources {
                timeout_seconds: 3_600,
            },
            launcher_journal_version: None,
        });
        let error = validate_resume_manifest_identity(
            &legacy,
            &manifest,
            ResumeManifestDriftAllowance::STRICT,
        )
        .expect_err("an older unlimited run must never be reexecuted under an invented deadline");
        assert!(error.to_string().contains("active execution deadline"));

        validate_resume_manifest_identity(
            &legacy,
            &manifest,
            ResumeManifestDriftAllowance {
                execution_timeout: true,
            },
        )
        .expect("captured-only validation may explicitly ignore the missing runtime deadline");
        assert_eq!(legacy.execution_timeout_seconds, None);
    }

    #[test]
    fn comparable_scope_contract_tracks_permissions_but_not_reapproval_metadata() {
        let manifest = comparison_scope_manifest();
        let asset = comparison_scope_asset();
        let grant = comparison_scope_grant();
        let baseline =
            comparable_scope_contract_sha256(&manifest, &[&asset], std::slice::from_ref(&grant))
                .expect("baseline scope contract");

        let mut reapproved = grant.clone();
        reapproved.id = "grant-2".into();
        reapproved.confirmed_by = "operator-b".into();
        reapproved.confirmed_at += Duration::hours(1);
        reapproved.notes = Some("new audit note".into());
        assert_eq!(
            baseline,
            comparable_scope_contract_sha256(&manifest, &[&asset], &[reapproved])
                .expect("equivalent reapproval")
        );

        let mut changed_permission = grant;
        changed_permission.permission = ScanPermission::InventoryRead;
        assert_ne!(
            baseline,
            comparable_scope_contract_sha256(&manifest, &[&asset], &[changed_permission])
                .expect("changed permission contract")
        );
    }

