    #[test]
    fn standard_redaction_pipeline_is_shared_by_all_document_formats() {
        const SENTINEL: &str = "SENSITIVE_DOCUMENT_SENTINEL_73be19";
        let time = Utc::now();
        let mut case = AssessmentCase::new(
            SENTINEL.into(),
            OrganizationProfile {
                organization_name: SENTINEL.into(),
                employee_range: "1-10".into(),
                data_classes: vec![DataClass::General],
                notes: Some(SENTINEL.into()),
            },
        );
        case.id = "case-redaction".into();
        case.scan_runs.push(ScanRun {
            id: "run-redaction".into(),
            case_id: case.id.clone(),
            sequence: 1,
            created_at: time,
            completed_at: Some(time),
            request_outcome: None,
            knowledge_cutoff: time,
            ai_system_applicable: false,
            ai_system_applicability: Default::default(),
            ai_generated_artifact: Default::default(),
            verification_baseline_run_id: None,
            scope_grant_ids: vec![],
            scope_grant_snapshots: vec![],
            engine_admission_issues: Vec::new(),
            engine_runs: vec![],
        });
        let options = ExportOptions::default();
        assert!(
            String::from_utf8(
                canonical_json_bytes(
                    &case,
                    "run-redaction",
                    &ExportOptions {
                        redaction: RedactionProfile::None,
                        include_raw_artifacts: false,
                        locale: crate::export::ReportLocale::En,
                    },
                )
                .unwrap(),
            )
            .unwrap()
            .contains(SENTINEL),
            "the document sentinel fixture must be meaningful"
        );

        let document_case = case_for_document_export(&case, &options);
        let beginner_json = canonical_json_bytes(&case, "run-redaction", &options).unwrap();
        let beginner_document: Value = serde_json::from_slice(&beginner_json).unwrap();
        assert_eq!(beginner_document["export_kind"], "beginner_master_report");
        assert_eq!(
            beginner_document["report"]["state"]["summary"],
            "no_checks_completed"
        );
        assert!(beginner_document.get("case").is_none());
        let readable_html =
            String::from_utf8(html_report_bytes(&case, "run-redaction", &options).unwrap())
                .unwrap();
        for required_heading in [
            "What you asked to scan",
            "What was actually tested",
            "What was not tested",
            "What to do next",
            "Problems found",
            "Technical details",
        ] {
            assert!(
                readable_html.contains(required_heading),
                "readable HTML omitted {required_heading}"
            );
        }
        let documents = [
            ("canonical_json", beginner_json),
            (
                "framework_report",
                export_master_framework_report_bytes(&document_case, "run-redaction").unwrap(),
            ),
            (
                "ocsf",
                export_ocsf_finding_events_bytes(&document_case, "run-redaction").unwrap(),
            ),
            (
                "oscal",
                export_oscal_assessment_results_bytes(&document_case, "run-redaction").unwrap(),
            ),
            (
                "html",
                html_report_bytes(&case, "run-redaction", &options).unwrap(),
            ),
        ];
        for (format, bytes) in documents {
            assert!(
                !bytes
                    .windows(SENTINEL.len())
                    .any(|window| window == SENTINEL.as_bytes()),
                "{format} leaked a standard-redaction sentinel"
            );
        }
    }

