    #[test]
    fn beginner_visible_html_uses_friendly_labels_and_keeps_exact_ids_collapsed() {
        let fixture = Fixture::new();
        let prepared = crate::localhost_quick_scan::prepare_localhost_quick_scan(
            &fixture.storage,
            fixture.engines.manifests(),
            9001,
        )
        .unwrap();
        let mut case = fixture
            .storage
            .get_case(&prepared.prepared.case_id)
            .unwrap();
        let observed = DateTime::parse_from_rfc3339("2026-09-01T12:34:56.123456789Z")
            .unwrap()
            .with_timezone(&Utc);
        let started = observed - Duration::seconds(1);
        let run = case
            .scan_runs
            .iter_mut()
            .find(|run| run.id == prepared.prepared.scan_run_id)
            .unwrap();
        run.completed_at = Some(observed);
        let task = run
            .engine_runs
            .iter_mut()
            .find(|task| task.id == prepared.prepared.engine_run_id)
            .unwrap();
        let target_id = task.asset_ids[0].clone();
        task.status = EngineRunStatus::Completed;
        task.phase = "completed".into();
        task.progress_percent = 100;
        task.started_at = Some(started);
        task.finished_at = Some(observed);
        task.exit_code = Some(0);
        task.cleanup_removed = Some(true);
        task.localhost_tcp_observation = Some(crate::domain::LocalhostTcpObservation {
            outcome: crate::domain::LocalhostTcpOutcome::Reachable,
            observed_at: observed,
        });
        case.status = CaseStatus::ReadyForHandoff;
        case.updated_at = observed;

        let options = ExportOptions {
            redaction: RedactionProfile::None,
            include_raw_artifacts: false,
            locale: crate::export::ReportLocale::En,
        };
        let html = String::from_utf8(
            html_report_bytes(&case, &prepared.prepared.scan_run_id, &options).unwrap(),
        )
        .unwrap();
        let (beginner_visible, technical_details) = html
            .split_once("<details class=\"technical\"")
            .expect("readable report keeps technical details in a separate collapsed section");

        for expected in [
            "Quick discovery",
            "Web service",
            "Completed",
            "saved task settings",
            "127.0.0.1:9001",
            "2026-09-01 12:34:56 UTC",
        ] {
            assert!(
                beginner_visible.contains(expected),
                "beginner-visible HTML omitted friendly text {expected}"
            );
        }
        for machine_facing in [
            "quick_discovery",
            "web_service",
            "tested_complete",
            "frozen_task_contract",
            target_id.as_str(),
            ".123456789",
            "T12:34:56",
        ] {
            assert!(
                !beginner_visible.contains(machine_facing),
                "beginner-visible HTML leaked machine-facing value {machine_facing}"
            );
        }
        assert!(
            technical_details.contains(&target_id),
            "collapsed technical details retain the exact target ID for auditability"
        );
        assert!(!html.contains("<details class=\"technical\" open"));
        assert!(html.contains(concat!(
            "Content-Security-Policy\" content=\"default-src 'none'; ",
            "style-src 'unsafe-inline'; base-uri 'none'; form-action 'none'"
        )));
        assert!(html.contains("<html lang=\"en\">"));
        assert!(html.contains("What was actually tested"));
        assert!(html.contains("Framework references are informational mappings"));

        let zh_options = ExportOptions {
            redaction: RedactionProfile::None,
            include_raw_artifacts: false,
            locale: crate::export::ReportLocale::ZhHant,
        };
        let zh_html = String::from_utf8(
            html_report_bytes(&case, &prepared.prepared.scan_run_id, &zh_options).unwrap(),
        )
        .unwrap();
        let zh_preview = fixture
            .service()
            .preview_export(
                &case.id,
                &prepared.prepared.scan_run_id,
                CaseExportFormat::Html,
                &zh_options,
            )
            .unwrap();

        assert_eq!(zh_preview.locale, crate::export::ReportLocale::ZhHant);
        assert!(!zh_preview.include_raw_evidence);
        for expected in [
            "<html lang=\"zh-Hant\">",
            "實際測試的內容",
            "已完成",
            "框架參照僅供資訊對照，不代表取得認證或符合規範。",
            "AIDEFEND 參照屬於獨立、非官方的對照",
            "2026年09月01日 12:34:56 UTC",
        ] {
            assert!(
                zh_html.contains(expected),
                "zh-Hant HTML omitted {expected}"
            );
        }
        for english_only in [
            "<html lang=\"en\">",
            "What was actually tested",
            "Framework references are informational mappings",
        ] {
            assert!(
                !zh_html.contains(english_only),
                "zh-Hant HTML retained English catalog text {english_only}"
            );
        }

        let canonical = String::from_utf8(
            canonical_json_bytes(&case, &prepared.prepared.scan_run_id, &options).unwrap(),
        )
        .unwrap();
        for canonical_value in [
            "quick_discovery",
            "web_service",
            "tested_complete",
            "frozen_task_contract",
            target_id.as_str(),
        ] {
            assert!(
                canonical.contains(canonical_value),
                "canonical JSON unexpectedly changed {canonical_value}"
            );
        }
    }

    #[test]
    fn finding_groups_are_reversible_and_never_replace_canonical_findings() {
        let fixture = Fixture::new();
        let mut case = fixture.create();
        let now = Utc::now();
        case.scan_runs.push(ScanRun {
            id: "run-1".into(),
            case_id: case.id.clone(),
            sequence: 1,
            created_at: now,
            completed_at: Some(now),
            request_outcome: None,
            knowledge_cutoff: now,
            ai_system_applicable: false,
            ai_system_applicability: Default::default(),
            ai_generated_artifact: Default::default(),
            verification_baseline_run_id: None,
            scope_grant_ids: vec![],
            scope_grant_snapshots: vec![],
            engine_admission_issues: Vec::new(),
            engine_runs: vec![],
        });
        for (id, fingerprint, priority) in [
            ("finding-a", "engine-a:rule", 40),
            ("finding-b", "engine-b:rule", 80),
        ] {
            case.findings.push(Finding {
                id: id.into(),
                case_id: case.id.clone(),
                first_seen_run_id: "run-1".into(),
                last_seen_run_id: "run-1".into(),
                fingerprint: fingerprint.into(),
                title: format!("Independent {id}"),
                plain_language_summary: "Independent canonical record".into(),
                possible_impact: "Requires human review".into(),
                severity: Severity::Medium,
                confidence: Confidence::High,
                priority,
                priority_reasons: vec![],
                asset_ids: vec!["asset-1".into()],
                evidence: vec![Evidence {
                    id: format!("evidence-{id}"),
                    finding_id: id.into(),
                    run_id: "run-1".into(),
                    engine_run_id: None,
                    kind: EvidenceKind::Configuration,
                    engine_id: fingerprint.split(':').next().unwrap().into(),
                    source_rule: None,
                    result_pointer_sha256: None,
                    observed_at: now,
                    summary: format!("Independent evidence for {id}"),
                    artifact_id: format!("artifact-{id}"),
                    artifact_sha256: "a".repeat(64),
                    pointer: Some(format!("/findings/{id}")),
                    redacted: false,
                }],
                control_references: vec![],
                recommendation: "Review without automatic remediation".into(),
                verification_guidance: "Re-run the responsible engine".into(),
                rollback_considerations: None,
                official_references: vec![],
                recommended_expert_type: "Security reviewer".into(),
                status: FindingStatus::Unreviewed,
                tags: vec![],
            });
            case.finding_observations.push(FindingObservation {
                id: format!("observation-{id}"),
                run_id: "run-1".into(),
                finding_id: id.into(),
                fingerprint: fingerprint.into(),
                asset_ids: vec!["asset-1".into()],
                engine_ids: vec![fingerprint.split(':').next().unwrap().into()],
                severity: Severity::Medium,
                confidence: Confidence::High,
                evidence_hashes: vec!["a".repeat(64)],
                observed_at: now,
                finding_snapshot: None,
            });
        }
        case.updated_at = now;
        let canonical_findings = serde_json::to_value(&case.findings).unwrap();
        fixture
            .storage
            .save_case(&mut case, "test.findings")
            .unwrap();

        let group_title = "Related access observations";
        let group_rationale = "A human should review the shared access path together.";
        let group_actor = "Private grouping operator";
        let grouped = fixture
            .service()
            .group_findings(
                &case.id,
                FindingGroupRequest {
                    title: group_title.into(),
                    finding_ids: vec!["finding-b".into(), "finding-a".into()],
                    rationale: group_rationale.into(),
                    grouped_by: group_actor.into(),
                },
            )
            .unwrap();
        assert_eq!(grouped.findings.len(), 2);
        assert_eq!(
            serde_json::to_value(&grouped.findings).unwrap(),
            canonical_findings
        );
        assert_eq!(grouped.finding_groups.len(), 1);
        assert_eq!(
            grouped.finding_groups[0].finding_ids,
            ["finding-a", "finding-b"]
        );
        assert_eq!(grouped.finding_group_events.len(), 1);
        assert_eq!(
            grouped.finding_group_events[0].action,
            FindingGroupAction::Created
        );
        let created_event = serde_json::to_value(&grouped.finding_group_events[0]).unwrap();

        let unredacted_html = String::from_utf8(
            html_report_bytes(
                &grouped,
                "run-1",
                &ExportOptions {
                    redaction: RedactionProfile::None,
                    include_raw_artifacts: false,
                    locale: crate::export::ReportLocale::En,
                },
            )
            .unwrap(),
        )
        .unwrap();
        assert!(unredacted_html.contains("Reversible finding groups"));
        assert!(unredacted_html.contains(group_title));
        assert!(unredacted_html.contains(group_rationale));
        assert!(unredacted_html.contains("Independent finding-a"));
        assert!(unredacted_html.contains("Independent finding-b"));
        assert!(unredacted_html.contains("Report order #1"));
        let beginner_problem_section = unredacted_html
            .split("<h2>Problems found</h2>")
            .nth(1)
            .unwrap()
            .split("<details class=\"technical\">")
            .next()
            .unwrap();
        assert!(
            beginner_problem_section
                .find("Independent finding-b")
                .unwrap()
                < beginner_problem_section
                    .find("Independent finding-a")
                    .unwrap()
        );
        assert!(unredacted_html.contains("Priority: 80"));
        assert!(unredacted_html.contains("Priority: 40"));

        let redacted_html = String::from_utf8(
            html_report_bytes(&grouped, "run-1", &ExportOptions::default()).unwrap(),
        )
        .unwrap();
        assert!(redacted_html.contains("redacted finding group"));
        for sensitive in [group_title, group_rationale, group_actor] {
            assert!(!redacted_html.contains(sensitive));
        }

        let unredacted_report =
            beginner_report_for_export(&grouped, "run-1", RedactionProfile::None).unwrap();
        assert_eq!(unredacted_report.schema_version, "1.1.0");
        assert_eq!(unredacted_report.finding_groups.len(), 1);
        assert_eq!(unredacted_report.finding_groups[0].title, group_title);
        assert_eq!(
            unredacted_report.finding_groups[0].rationale,
            group_rationale
        );
        assert_eq!(unredacted_report.finding_groups[0].actor, group_actor);
        assert!(
            unredacted_report.finding_groups[0]
                .members
                .iter()
                .all(|member| member.observed_in_selected_run)
        );

        let redacted_report =
            beginner_report_for_export(&grouped, "run-1", RedactionProfile::Standard).unwrap();
        assert_eq!(
            redacted_report.finding_groups[0].title,
            "[redacted finding group]"
        );
        assert_eq!(
            redacted_report.finding_groups[0].rationale,
            "[redacted grouping rationale]"
        );
        assert_eq!(redacted_report.finding_groups[0].actor, "[redacted]");
        assert_eq!(
            redacted_report.finding_groups[0].group_id,
            unredacted_report.finding_groups[0].group_id
        );
        assert_eq!(
            redacted_report.finding_groups[0].members,
            unredacted_report.finding_groups[0].members
        );
        assert_eq!(
            redacted_report.coverage_counts,
            unredacted_report.coverage_counts
        );

        let grouped_canonical =
            canonical_json_bytes(&grouped, "run-1", &ExportOptions::default()).unwrap();
        let grouped_canonical: Value = serde_json::from_slice(&grouped_canonical).unwrap();
        assert_eq!(grouped_canonical["schema_version"], "1.1.0");
        assert_eq!(grouped_canonical["report"]["schema_version"], "1.1.0");
        assert_eq!(
            grouped_canonical
                .pointer("/report/finding_groups")
                .and_then(Value::as_array)
                .unwrap()
                .len(),
            1
        );

        assert!(
            fixture
                .service()
                .group_findings(
                    &case.id,
                    FindingGroupRequest {
                        title: "Overlapping group".into(),
                        finding_ids: vec!["finding-a".into(), "finding-b".into()],
                        rationale: "Must not create a second active presentation owner".into(),
                        grouped_by: "Another operator".into(),
                    },
                )
                .is_err()
        );
        assert_eq!(
            fixture
                .service()
                .show_case(&case.id)
                .unwrap()
                .finding_group_events
                .len(),
            1
        );

        let group_id = grouped.finding_groups[0].id.clone();
        let removal_actor = "Private removal operator";
        let removal_reason = "The shared path was disproven; retain both observations.";
        let ungrouped = fixture
            .service()
            .ungroup_findings(
                &case.id,
                FindingUngroupRequest {
                    group_id,
                    removed_by: removal_actor.into(),
                    reason: removal_reason.into(),
                },
            )
            .unwrap();
        assert!(ungrouped.finding_groups.is_empty());
        assert_eq!(ungrouped.findings.len(), 2);
        assert_eq!(
            serde_json::to_value(&ungrouped.findings).unwrap(),
            canonical_findings
        );
        assert_eq!(ungrouped.finding_group_events.len(), 2);
        assert_eq!(
            serde_json::to_value(&ungrouped.finding_group_events[0]).unwrap(),
            created_event
        );
        assert_eq!(
            ungrouped.finding_group_events[1].action,
            FindingGroupAction::Removed
        );
        assert_eq!(ungrouped.finding_group_events[1].title, group_title);
        assert_eq!(
            ungrouped.finding_group_events[1].finding_ids,
            ["finding-a", "finding-b"]
        );
        assert_eq!(ungrouped.finding_group_events[1].rationale, removal_reason);
        assert!(
            ungrouped
                .findings
                .iter()
                .all(|finding| finding.fingerprint.starts_with("engine-"))
        );

        let canonical =
            canonical_json_bytes(&ungrouped, "run-1", &ExportOptions::default()).unwrap();
        let canonical_text = String::from_utf8(canonical.clone()).unwrap();
        for sensitive in [
            group_title,
            group_rationale,
            group_actor,
            removal_actor,
            removal_reason,
        ] {
            assert!(!canonical_text.contains(sensitive));
        }
        let canonical: Value = serde_json::from_slice(&canonical).unwrap();
        assert_eq!(canonical["export_kind"], "beginner_master_report");
        assert_eq!(canonical["schema_version"], "1.1.0");
        assert_eq!(canonical["report"]["schema_version"], "1.1.0");
        assert_eq!(
            canonical
                .pointer("/report/findings")
                .and_then(Value::as_array)
                .unwrap()
                .len(),
            2
        );
        assert!(
            canonical
                .pointer("/report/finding_groups")
                .and_then(Value::as_array)
                .unwrap()
                .is_empty()
        );
        assert!(canonical.get("case").is_none());
    }

    #[test]
    fn lifecycle_persists_across_reopen_and_delete_returns_explicit_artifact_plan() {
        let directory = tempfile::tempdir().unwrap();
        let database = directory.path().join("casework.db");
        let case_id = {
            let storage = Storage::open(&database).unwrap();
            let engines = EngineRegistry::load_builtin().unwrap();
            let adapters = AdapterRegistry::default();
            let service = CaseService::new(
                &storage,
                &engines,
                &adapters,
                directory.path().join("artifacts"),
                directory.path().join("key"),
            );
            service
                .create_case(&CreateCaseRequest {
                    title: "Persistent".into(),
                    organization_name: "Example".into(),
                    employee_range: "1-10".into(),
                    assessment_intent: None,
                    ai_generated_artifact: Default::default(),
                    data_classes: vec![],
                    requested_activities: vec![],
                    source_kinds: vec![],
                    not_applicable_source_kinds: vec![],
                    declared_assets: vec![],
                    notes: None,
                })
                .unwrap()
                .id
        };
        let storage = Storage::open(&database).unwrap();
        let engines = EngineRegistry::load_builtin().unwrap();
        let adapters = AdapterRegistry::default();
        let service = CaseService::new(
            &storage,
            &engines,
            &adapters,
            directory.path().join("artifacts"),
            directory.path().join("key"),
        );
        assert_eq!(service.show_case(&case_id).unwrap().title, "Persistent");
        let case_artifacts = directory.path().join("artifacts").join(&case_id);
        fs::create_dir_all(&case_artifacts).unwrap();
        fs::write(case_artifacts.join("evidence.bin"), b"sensitive evidence").unwrap();
        let deletion = service.delete_case(&case_id).unwrap();
        assert!(deletion.database_record_deleted);
        assert!(deletion.artifacts.requires_explicit_confirmation);
        assert!(service.show_case(&case_id).is_err());
        assert_eq!(
            service.list_artifact_deletion_obligations().unwrap(),
            vec![deletion.artifacts.clone()]
        );
        drop(service);
        let reopened_service = CaseService::new(
            &storage,
            &engines,
            &adapters,
            directory.path().join("artifacts"),
            directory.path().join("key"),
        );
        assert_eq!(
            reopened_service
                .list_artifact_deletion_obligations()
                .unwrap(),
            vec![deletion.artifacts.clone()]
        );
        assert!(
            reopened_service
                .delete_case_artifacts(
                    &case_id,
                    &deletion.artifacts.exact_path,
                    "wrong confirmation",
                )
                .is_err()
        );
        let removed = reopened_service
            .delete_case_artifacts(
                &case_id,
                &deletion.artifacts.exact_path,
                &format!("DELETE {case_id}"),
            )
            .unwrap();
        assert!(removed.removed);
        assert!(!removed.recoverable);
        assert!(!case_artifacts.exists());
        assert!(
            reopened_service
                .list_artifact_deletion_obligations()
                .unwrap()
                .is_empty()
        );
        assert!(matches!(
            reopened_service.delete_case_artifacts(
                &case_id,
                &deletion.artifacts.exact_path,
                &format!("DELETE {case_id}"),
            ),
            Err(AppError::NotAuthorized(_))
        ));
    }

