    #[test]
    fn rescan_plan_atomically_persists_verification_intent_and_finalizes_idempotently() {
        let fixture = Fixture::new();
        let (case_id, baseline_run_id) = repository_case_with_completed_baseline(&fixture);
        let service = fixture.service();

        let runs_before = service.show_case(&case_id).unwrap().scan_runs.len();
        assert!(
            service
                .plan_rescan(
                    &case_id,
                    "missing-baseline",
                    ScanPlanRequest {
                        engine_ids: vec!["gitleaks".into()],
                    },
                )
                .is_err()
        );
        assert_eq!(
            service.show_case(&case_id).unwrap().scan_runs.len(),
            runs_before,
            "an invalid baseline must not persist an ordinary scan before failing"
        );

        let rescan = service
            .plan_rescan(
                &case_id,
                &baseline_run_id,
                ScanPlanRequest {
                    engine_ids: vec!["gitleaks".into()],
                },
            )
            .unwrap();
        assert_eq!(rescan.plan.executable.len(), 1);
        assert_eq!(
            rescan.plan.scan_run.verification_baseline_run_id.as_deref(),
            Some(baseline_run_id.as_str())
        );
        let planned = service.show_case(&case_id).unwrap();
        assert_eq!(planned.scan_runs.len(), runs_before + 1);
        assert_eq!(planned.status, CaseStatus::Verifying);
        assert_eq!(
            planned
                .scan_runs
                .last()
                .unwrap()
                .verification_baseline_run_id,
            Some(baseline_run_id.clone())
        );
        assert!(
            service
                .finalize_verification_if_terminal(&case_id, &rescan.plan.scan_run.id)
                .unwrap()
                .is_none(),
            "a queued verification run cannot be compared"
        );

        let mut terminal = planned;
        let current = terminal.scan_runs.last_mut().unwrap();
        for engine_run in &mut current.engine_runs {
            engine_run.status = EngineRunStatus::Completed;
            engine_run.progress_percent = 100;
            engine_run.phase = "completed".into();
            engine_run.finished_at = Some(Utc::now());
        }
        current.completed_at = Some(Utc::now());
        fixture
            .storage
            .save_case(&mut terminal, "test.verification_terminal")
            .unwrap();

        let first = service
            .finalize_verification_if_terminal(&case_id, &rescan.plan.scan_run.id)
            .unwrap()
            .unwrap();
        let replay = service
            .finalize_verification_if_terminal(&case_id, &rescan.plan.scan_run.id)
            .unwrap()
            .unwrap();
        assert_eq!(first.id, replay.id);
        let finalized = service.show_case(&case_id).unwrap();
        assert_eq!(finalized.comparisons.len(), 1);
        assert_eq!(finalized.status, CaseStatus::ReadyForHandoff);
    }

    #[test]
    fn historical_verification_finalization_preserves_a_newer_live_run_status() {
        let fixture = Fixture::new();
        let (case_id, baseline_run_id) = repository_case_with_completed_baseline(&fixture);
        let service = fixture.service();
        let verification = service
            .plan_rescan(
                &case_id,
                &baseline_run_id,
                ScanPlanRequest {
                    engine_ids: vec!["gitleaks".into()],
                },
            )
            .unwrap();
        let verification_run_id = verification.plan.scan_run.id.clone();
        let mut stored = service.show_case(&case_id).unwrap();
        let verification_run = stored
            .scan_runs
            .iter_mut()
            .find(|run| run.id == verification_run_id)
            .unwrap();
        for engine in &mut verification_run.engine_runs {
            engine.status = EngineRunStatus::Completed;
            engine.progress_percent = 100;
            engine.phase = "completed".into();
            engine.finished_at = Some(Utc::now());
        }
        verification_run.completed_at = Some(Utc::now());
        fixture
            .storage
            .save_case(&mut stored, "test.verification_terminal_before_new_run")
            .unwrap();

        let newer = service
            .plan_scan(
                &case_id,
                ScanPlanRequest {
                    engine_ids: vec!["gitleaks".into()],
                },
            )
            .unwrap();
        let before = service.show_case(&case_id).unwrap();
        assert_eq!(before.status, CaseStatus::Scanning);

        service
            .finalize_verification_if_terminal(&case_id, &verification_run_id)
            .unwrap()
            .expect("historical comparison is persisted");
        let after = service.show_case(&case_id).unwrap();
        assert_eq!(after.status, CaseStatus::Scanning);
        assert!(after.comparisons.iter().any(|comparison| {
            comparison.baseline_run_id == baseline_run_id
                && comparison.current_run_id == verification_run_id
        }));
        let newer_run = after
            .scan_runs
            .iter()
            .find(|run| run.id == newer.scan_run.id)
            .unwrap();
        assert!(newer_run.completed_at.is_none());
        assert!(
            newer_run
                .engine_runs
                .iter()
                .all(|engine| engine.status == EngineRunStatus::Queued)
        );
    }

    #[test]
    fn executable_empty_and_startup_paths_complete_pending_verification_once() {
        let fixture = Fixture::new();
        let (case_id, baseline_run_id) = repository_case_with_completed_baseline(&fixture);
        let service = fixture.service();

        let empty = service
            .plan_rescan(
                &case_id,
                &baseline_run_id,
                ScanPlanRequest {
                    engine_ids: vec!["missing".into()],
                },
            )
            .unwrap();
        assert!(empty.plan.executable.is_empty());
        assert!(empty.plan.scan_run.completed_at.is_some());
        assert_eq!(
            empty.plan.scan_run.verification_baseline_run_id.as_deref(),
            Some(baseline_run_id.as_str())
        );
        let empty_comparison = service
            .finalize_verification_if_terminal(&case_id, &empty.plan.scan_run.id)
            .unwrap()
            .unwrap();
        assert_eq!(empty_comparison.current_run_id, empty.plan.scan_run.id);

        let crash_window = service
            .plan_rescan(
                &case_id,
                &baseline_run_id,
                ScanPlanRequest {
                    engine_ids: vec!["missing".into()],
                },
            )
            .unwrap();
        assert!(crash_window.plan.executable.is_empty());
        assert_eq!(service.show_case(&case_id).unwrap().comparisons.len(), 1);
        assert_eq!(service.reconcile_terminal_verifications().unwrap(), 1);
        assert_eq!(service.reconcile_terminal_verifications().unwrap(), 0);
        let reconciled = service.show_case(&case_id).unwrap();
        assert_eq!(reconciled.comparisons.len(), 2);
        assert!(reconciled.comparisons.iter().any(|comparison| {
            comparison.baseline_run_id == baseline_run_id
                && comparison.current_run_id == crash_window.plan.scan_run.id
        }));
    }

    #[test]
    fn live_resume_only_requeues_paused_workers_and_preserves_sibling_evidence() {
        let fixture = Fixture::new();
        let case = fixture.create();
        let (_, asset_id) = fixture.discovered_asset(&case.id, AssetKind::Repository);
        let service = fixture.service();
        service
            .approve_scope(
                &case.id,
                ScopeApprovalRequest {
                    asset_id,
                    permissions: vec![ScanPermission::LocalArtifactRead],
                    confirmed_by: "Owner".into(),
                    expires_at: None,
                    authorization_reference: None,
                    notes: None,
                    external_scope: None,
                },
            )
            .unwrap();
        let original = service
            .plan_scan(
                &case.id,
                ScanPlanRequest {
                    engine_ids: vec!["kics".into(), "semgrep".into()],
                },
            )
            .unwrap();

        let mut stored = service.show_case(&case.id).unwrap();
        let run = stored
            .scan_runs
            .iter_mut()
            .find(|run| run.id == original.scan_run.id)
            .unwrap();
        let now = Utc::now();
        let paused = run
            .engine_runs
            .iter_mut()
            .find(|engine| engine.engine_id == "kics")
            .unwrap();
        paused.status = EngineRunStatus::Paused;
        paused.phase = "paused".into();
        paused.progress_percent = 45;
        paused.started_at = Some(now);
        paused.error_code = Some("pause_context".into());
        paused.error_message = Some("worker retained its pre-pause context".into());

        let failed = run
            .engine_runs
            .iter_mut()
            .find(|engine| engine.engine_id == "semgrep")
            .unwrap();
        let mut failed_checkpoint =
            ExecutionCheckpoint::from_resume_token(failed.resume_token.as_deref().unwrap())
                .unwrap();
        failed_checkpoint.stage = ExecutionStage::Failed;
        failed_checkpoint.cleanup_completed = true;
        failed_checkpoint.last_error =
            Some("managed local engine launcher: engine exceeded its fixed runtime timeout".into());
        let failed_token = Some(failed_checkpoint.resume_token().unwrap());
        failed.status = EngineRunStatus::Failed;
        failed.phase = "execution_failed".into();
        failed.progress_percent = 95;
        failed.started_at = Some(now);
        failed.finished_at = Some(now);
        failed.error_code = Some("execution_failed".into());
        failed.error_message =
            Some("managed local engine launcher: engine exceeded its fixed runtime timeout".into());
        failed.resume_token = failed_token.clone();
        failed.cleanup_removed = Some(true);
        failed.cleanup_detail = Some("owned container removed after the failed run".into());
        failed.raw_artifact_ids = vec!["retained-artifact".into()];
        stored.status = CaseStatus::NeedsAttention;
        fixture
            .storage
            .save_case(&mut stored, "test.live_resume_mixed_state")
            .unwrap();

        let resumed = service
            .resume_scan(&case.id, &original.scan_run.id)
            .unwrap();
        let run = resumed
            .scan_runs
            .iter()
            .find(|run| run.id == original.scan_run.id)
            .unwrap();
        let paused = run
            .engine_runs
            .iter()
            .find(|engine| engine.engine_id == "kics")
            .unwrap();
        assert_eq!(paused.status, EngineRunStatus::Queued);
        assert_eq!(paused.phase, "queued_for_resume");
        assert_eq!(paused.progress_percent, 45);
        assert_eq!(paused.started_at, Some(now));
        assert_eq!(paused.error_code.as_deref(), Some("pause_context"));
        assert_eq!(
            paused.error_message.as_deref(),
            Some("worker retained its pre-pause context")
        );

        let failed = run
            .engine_runs
            .iter()
            .find(|engine| engine.engine_id == "semgrep")
            .unwrap();
        assert_eq!(failed.status, EngineRunStatus::Failed);
        assert_eq!(failed.phase, "execution_failed");
        assert_eq!(failed.progress_percent, 95);
        assert_eq!(failed.finished_at, Some(now));
        assert_eq!(failed.resume_token, failed_token);
        assert_eq!(failed.error_code.as_deref(), Some("execution_failed"));
        assert_eq!(
            failed.error_message.as_deref(),
            Some("managed local engine launcher: engine exceeded its fixed runtime timeout")
        );
        assert_eq!(failed.cleanup_removed, Some(true));
        assert_eq!(
            failed.cleanup_detail.as_deref(),
            Some("owned container removed after the failed run")
        );
        assert_eq!(failed.raw_artifact_ids, vec!["retained-artifact"]);
    }

    struct ReleaseDriftResumeFixture {
        case_id: Id,
        run_id: Id,
        engine_run_id: Id,
        output_path: PathBuf,
    }

    fn stage_timeout_and_mapping_drift_captured_resume(
        fixture: &Fixture,
        engine_ids: Vec<String>,
        output_bytes: &[u8],
    ) -> ReleaseDriftResumeFixture {
        let case = fixture.create();
        let (_, asset_id) = fixture.discovered_asset(&case.id, AssetKind::Repository);
        let service = fixture.service();
        service
            .approve_scope(
                &case.id,
                ScopeApprovalRequest {
                    asset_id,
                    permissions: vec![ScanPermission::LocalArtifactRead],
                    confirmed_by: "Owner".into(),
                    expires_at: None,
                    authorization_reference: None,
                    notes: None,
                    external_scope: None,
                },
            )
            .unwrap();
        let plan = service
            .plan_scan(&case.id, ScanPlanRequest { engine_ids })
            .unwrap();
        let mut stored = service.show_case(&case.id).unwrap();
        let run = stored
            .scan_runs
            .iter_mut()
            .find(|run| run.id == plan.scan_run.id)
            .unwrap();
        let engine_run = run
            .engine_runs
            .iter_mut()
            .find(|engine_run| engine_run.engine_id == "trufflehog")
            .unwrap();
        let mut checkpoint =
            ExecutionCheckpoint::from_resume_token(engine_run.resume_token.as_deref().unwrap())
                .unwrap();
        let relative_directory = format!(
            "{}/{}/{}/attempt-{}/",
            case.id, run.id, engine_run.id, checkpoint.attempt
        );
        let artifact_specs = [
            (
                "trufflehog-output",
                format!("{relative_directory}output/trufflehog.jsonl"),
                "application/x-ndjson",
                output_bytes,
            ),
            (
                "trufflehog-stdout",
                format!("{relative_directory}raw/stdout.log"),
                "text/plain",
                b"scanner diagnostic\n".as_slice(),
            ),
            (
                "trufflehog-stderr",
                format!("{relative_directory}raw/stderr.log"),
                "text/plain",
                b"".as_slice(),
            ),
        ];
        let artifact_root = fixture.directory.path().join("artifacts");
        let mut artifacts = Vec::new();
        for (suffix, relative_path, media_type, bytes) in artifact_specs {
            let path = artifact_root.join(&relative_path);
            fs::create_dir_all(path.parent().unwrap()).unwrap();
            fs::write(&path, bytes).unwrap();
            artifacts.push(RawArtifact {
                id: format!("artifact-{suffix}"),
                case_id: case.id.clone(),
                run_id: run.id.clone(),
                engine_run_id: engine_run.id.clone(),
                relative_path,
                media_type: media_type.into(),
                sha256: sha256_bytes(bytes),
                byte_length: bytes.len() as u64,
                created_at: Utc::now(),
                contains_sensitive_data: true,
            });
        }
        let artifact_ids = artifacts
            .iter()
            .map(|artifact| artifact.id.clone())
            .collect::<Vec<_>>();
        let output_path = artifact_root.join(&artifacts[0].relative_path);
        checkpoint.stage = ExecutionStage::CapturedAwaitingAdapter;
        checkpoint.artifact_ids = artifact_ids.clone();
        checkpoint.cleanup_completed = true;
        checkpoint.last_error =
            Some("adapter normalization was incomplete; raw evidence was retained".into());
        engine_run.status = EngineRunStatus::PartiallyCompleted;
        engine_run.phase = "captured_awaiting_adapter".into();
        engine_run.progress_percent = 85;
        engine_run.finished_at = Some(Utc::now());
        engine_run.resume_token = Some(checkpoint.resume_token().unwrap());
        engine_run.raw_artifact_ids = artifact_ids;
        engine_run.mapping_version = Some("2026-08-26.1".into());
        engine_run.execution_timeout_seconds = None;
        let engine_run_id = engine_run.id.clone();
        run.completed_at = Some(Utc::now());
        stored.raw_artifacts.extend(artifacts);
        stored.status = CaseStatus::NeedsAttention;
        fixture
            .storage
            .save_case(&mut stored, "test.release_drift_captured_resume")
            .unwrap();

        ReleaseDriftResumeFixture {
            case_id: case.id,
            run_id: plan.scan_run.id,
            engine_run_id,
            output_path,
        }
    }

    #[test]
    fn execution_timeout_drift_allows_only_verified_empty_captured_jsonl_resume() {
        let fixture = Fixture::new();
        let staged = stage_timeout_and_mapping_drift_captured_resume(
            &fixture,
            vec!["trufflehog".into()],
            b"",
        );

        let resumed = fixture
            .service()
            .plan_resume(&staged.case_id, &staged.run_id)
            .expect("verified empty captured JSONL is independent of mapping catalogs");
        assert_eq!(resumed.executable.len(), 1);
        assert_eq!(resumed.executable[0].attempt, 1);
        assert_eq!(
            resumed.executable[0]
                .resume_checkpoint
                .as_ref()
                .unwrap()
                .resume_action(),
            crate::orchestrator::ResumeAction::AdaptCapturedArtifacts
        );
        let stored = fixture.service().show_case(&staged.case_id).unwrap();
        let engine_run = stored.scan_runs[0]
            .engine_runs
            .iter()
            .find(|engine_run| engine_run.id == staged.engine_run_id)
            .unwrap();
        assert_eq!(engine_run.mapping_version.as_deref(), Some("2026-08-26.1"));
        assert_eq!(engine_run.execution_timeout_seconds, None);
        assert!(engine_run.warnings.iter().any(|warning| {
            warning.contains("no finding or control reference can be remapped")
                && warning.contains("no scanner or runtime will be re-executed")
        }));
    }

    #[test]
    fn execution_timeout_drift_rejects_nonempty_or_tampered_captured_jsonl() {
        let nonempty = Fixture::new();
        let staged = stage_timeout_and_mapping_drift_captured_resume(
            &nonempty,
            vec!["trufflehog".into()],
            br#"{"DetectorName":"finding"}"#,
        );
        let error = nonempty
            .service()
            .plan_resume(&staged.case_id, &staged.run_id)
            .expect_err("nonempty JSONL could emit newly mapped control references");
        assert!(
            error
                .to_string()
                .contains("scan_preflight:resume_release_incompatible")
        );
        assert!(error.to_string().contains("not verified zero-byte JSONL"));
        assert!(error.to_string().contains("Start a new scan"));

        let tampered = Fixture::new();
        let staged = stage_timeout_and_mapping_drift_captured_resume(
            &tampered,
            vec!["trufflehog".into()],
            b"",
        );
        fs::write(&staged.output_path, b"tampered").unwrap();
        let error = tampered
            .service()
            .plan_resume(&staged.case_id, &staged.run_id)
            .expect_err("changed evidence must fail its durable length/hash inspection");
        assert!(error.to_string().contains("byte length differs"));
    }

