    #[test]
    fn interrupted_cleanup_failure_is_final_reportable_and_does_not_lock_new_work() {
        let fixture = Fixture::new();
        let case = fixture.create();
        let (_, asset_id) = fixture.discovered_asset(&case.id, AssetKind::Repository);
        let service = fixture.service();
        service
            .approve_scope(
                &case.id,
                ScopeApprovalRequest {
                    asset_id,
                    permissions: vec![ScanPermission::LocalArtifactRead],
                    confirmed_by: "Owner".into(),
                    expires_at: None,
                    authorization_reference: None,
                    notes: None,
                    external_scope: None,
                },
            )
            .unwrap();
        let original = service
            .plan_scan(
                &case.id,
                ScanPlanRequest {
                    engine_ids: vec!["gitleaks".into()],
                },
            )
            .unwrap();

        let mut running = service.show_case(&case.id).unwrap();
        let engine_run = &mut running.scan_runs[0].engine_runs[0];
        let mut checkpoint =
            ExecutionCheckpoint::from_resume_token(engine_run.resume_token.as_deref().unwrap())
                .unwrap();
        checkpoint.stage = ExecutionStage::Running;
        checkpoint.cleanup_completed = false;
        checkpoint.container_name = Some(
            crate::container_runtime::planned_container_name(
                &checkpoint.engine_id,
                &checkpoint.engine_run_id,
                checkpoint.attempt,
            )
            .unwrap(),
        );
        checkpoint.runtime_command_provenance =
            Some(crate::container_runtime::RuntimeCommandProvenance::Compatibility);
        checkpoint.runtime_provider = Some(crate::container_runtime::RuntimeProvider::Podman);
        checkpoint.artifact_ids = vec!["retained-partial-artifact".into()];
        engine_run.resume_token = Some(checkpoint.resume_token().unwrap());
        engine_run.raw_artifact_ids = checkpoint.artifact_ids.clone();
        fixture
            .storage
            .save_case(&mut running, "test.running_before_restart")
            .unwrap();

        assert_eq!(service.recover_interrupted_scans().unwrap(), 1);
        let interrupted = service.show_case(&case.id).unwrap();
        let interrupted_token = interrupted.scan_runs[0].engine_runs[0]
            .resume_token
            .clone()
            .unwrap();
        assert!(matches!(
            service.record_interrupted_cleanup_failure(
                &case.id,
                &original.scan_run.id,
                &original.scan_run.engine_runs[0].id,
                "not-the-stored-token",
                "must not be recorded",
            ),
            Err(AppError::NotAuthorized(_))
        ));

        let pending = service
            .record_interrupted_cleanup_failure(
                &case.id,
                &original.scan_run.id,
                &original.scan_run.engine_runs[0].id,
                &interrupted_token,
                "runtime was unavailable during exact reconciliation",
            )
            .unwrap();
        let pending_engine = &pending.scan_runs[0].engine_runs[0];
        assert_eq!(pending_engine.phase, "interrupted_restart_cleanup_pending");
        assert_eq!(pending_engine.status, EngineRunStatus::Failed);
        assert!(pending_engine.finished_at.is_some());
        assert!(pending.scan_runs[0].completed_at.is_some());
        assert_eq!(pending.status, CaseStatus::NeedsAttention);
        assert_eq!(
            pending_engine.raw_artifact_ids,
            vec!["retained-partial-artifact"]
        );
        let pending_token = pending_engine.resume_token.clone().unwrap();
        let pending_checkpoint = ExecutionCheckpoint::from_resume_token(&pending_token).unwrap();
        assert_eq!(pending_checkpoint.stage, ExecutionStage::CleanupPending);
        assert!(!pending_checkpoint.cleanup_completed);
        assert_eq!(
            pending_checkpoint.artifact_ids,
            vec!["retained-partial-artifact"]
        );

        // Upgrade compatibility: earlier v0.1.8 work could persist the exact
        // same obligation as Paused. Startup must migrate only the lifecycle
        // projection and leave its checkpoint/evidence byte-for-byte durable.
        let mut legacy_projection = pending.clone();
        legacy_projection.scan_runs[0].engine_runs[0].status = EngineRunStatus::Paused;
        legacy_projection.scan_runs[0].engine_runs[0].finished_at = None;
        legacy_projection.scan_runs[0].completed_at = None;
        fixture
            .storage
            .save_case(
                &mut legacy_projection,
                "test.legacy_cleanup_pending_projection",
            )
            .unwrap();
        assert_eq!(service.recover_interrupted_scans().unwrap(), 1);
        let pending = service.show_case(&case.id).unwrap();
        assert_eq!(
            pending.scan_runs[0].engine_runs[0].status,
            EngineRunStatus::Failed
        );
        assert_eq!(
            pending.scan_runs[0].engine_runs[0].resume_token.as_deref(),
            Some(pending_token.as_str())
        );
        assert_eq!(
            pending.scan_runs[0].engine_runs[0].raw_artifact_ids,
            vec!["retained-partial-artifact"]
        );
        assert!(pending.scan_runs[0].completed_at.is_some());

        let report = build_beginner_master_report(&pending, &original.scan_run.id).unwrap();
        assert_eq!(report.state.lifecycle, ReportLifecycle::Final);
        assert_eq!(
            report.state.summary,
            BeginnerReportSummary::NoChecksCompleted
        );
        assert_eq!(service.recover_interrupted_scans().unwrap(), 0);
        assert!(matches!(
            service.plan_resume(&case.id, &original.scan_run.id),
            Err(AppError::NotAvailable(_))
        ));
        assert!(matches!(
            service.resume_scan(&case.id, &original.scan_run.id),
            Err(AppError::NotAvailable(_))
        ));
        assert!(matches!(
            service.cancel_scan(&case.id, &original.scan_run.id),
            Err(AppError::NotAvailable(_))
        ));

        let after_rejected_transitions = service.show_case(&case.id).unwrap();
        let retained_engine = &after_rejected_transitions.scan_runs[0].engine_runs[0];
        assert_eq!(retained_engine.status, EngineRunStatus::Failed);
        assert_eq!(retained_engine.phase, "interrupted_restart_cleanup_pending");
        assert_eq!(
            retained_engine.resume_token.as_deref(),
            Some(pending_token.as_str())
        );
        assert_eq!(retained_engine.cleanup_removed, Some(false));
        assert_eq!(
            retained_engine.raw_artifact_ids,
            vec!["retained-partial-artifact"]
        );

        let independent = service
            .plan_scan(
                &case.id,
                ScanPlanRequest {
                    engine_ids: vec!["gitleaks".into()],
                },
            )
            .unwrap();
        assert_ne!(independent.scan_run.id, original.scan_run.id);
        assert_ne!(
            independent.executable[0].engine_run_id,
            original.scan_run.engine_runs[0].id
        );
        assert_eq!(independent.scan_run.sequence, 2);
        assert_eq!(independent.executable.len(), 1);
        let with_independent_work = service.show_case(&case.id).unwrap();
        assert_eq!(with_independent_work.scan_runs.len(), 2);
        assert_eq!(
            with_independent_work.scan_runs[0].engine_runs[0].status,
            EngineRunStatus::Failed
        );
        assert_eq!(
            with_independent_work.scan_runs[0].engine_runs[0]
                .resume_token
                .as_deref(),
            Some(pending_token.as_str())
        );

        let cleaned = service
            .record_interrupted_cleanup_success(
                &case.id,
                &original.scan_run.id,
                &original.scan_run.engine_runs[0].id,
                ExactRuntimeCleanupSuccess {
                    expected_resume_token: pending_token,
                    cleanup: CleanupOutcome {
                        removed: true,
                        detail: "removed exact immutable container object".into(),
                    },
                    orphan_credentials_removed: 1,
                },
            )
            .unwrap();
        let cleaned_engine = &cleaned.scan_runs[0].engine_runs[0];
        assert_eq!(cleaned_engine.phase, "interrupted_restart_cleaned");
        assert_eq!(cleaned_engine.status, EngineRunStatus::Failed);
        assert!(cleaned.scan_runs[0].completed_at.is_some());
        assert_eq!(cleaned.status, CaseStatus::Scanning);
        assert_eq!(cleaned_engine.cleanup_removed, Some(true));
        assert_eq!(
            cleaned_engine.raw_artifact_ids,
            vec!["retained-partial-artifact"]
        );
        assert!(cleaned_engine.warnings.iter().any(|warning| {
            warning.contains("Zeroized and removed 1 crash-left credential envelope")
        }));
        let cleaned_checkpoint =
            ExecutionCheckpoint::from_resume_token(cleaned_engine.resume_token.as_deref().unwrap())
                .unwrap();
        assert_eq!(cleaned_checkpoint.stage, ExecutionStage::Failed);
        assert!(cleaned_checkpoint.cleanup_completed);
        assert_eq!(cleaned_checkpoint.attempt, 1);
        assert!(cleaned_checkpoint.managed_network.is_none());
        assert_eq!(
            cleaned_checkpoint.artifact_ids,
            vec!["retained-partial-artifact"]
        );
        let after_cleanup = service.show_case(&case.id).unwrap();
        assert_eq!(
            after_cleanup.scan_runs[1].engine_runs[0].status,
            EngineRunStatus::Queued
        );
    }

    #[test]
    fn interrupted_run_is_paused_and_resumed_as_a_new_attempt_without_scope_widening() {
        let fixture = Fixture::new();
        let case = fixture.create();
        let (_, asset_id) = fixture.discovered_asset(&case.id, AssetKind::Repository);
        let service = fixture.service();
        service
            .approve_scope(
                &case.id,
                ScopeApprovalRequest {
                    asset_id,
                    permissions: vec![ScanPermission::LocalArtifactRead],
                    confirmed_by: "Owner".into(),
                    expires_at: None,
                    authorization_reference: None,
                    notes: None,
                    external_scope: None,
                },
            )
            .unwrap();
        let original = service
            .plan_scan(
                &case.id,
                ScanPlanRequest {
                    engine_ids: vec!["gitleaks".into()],
                },
            )
            .unwrap();
        assert_eq!(original.executable[0].attempt, 1);

        assert_eq!(service.recover_interrupted_scans().unwrap(), 1);
        let interrupted = service.show_case(&case.id).unwrap();
        assert_eq!(
            interrupted.scan_runs[0].engine_runs[0].status,
            EngineRunStatus::Failed
        );
        assert_eq!(
            interrupted.scan_runs[0].engine_runs[0]
                .error_code
                .as_deref(),
            Some("preflight_interrupted")
        );
        assert_eq!(service.recover_interrupted_scans().unwrap(), 0);

        let resumed = service
            .plan_resume(&case.id, &original.scan_run.id)
            .unwrap();
        assert_eq!(resumed.executable.len(), 1);
        assert_eq!(resumed.executable[0].attempt, 2);
        assert_eq!(
            resumed.scan_run.engine_runs[0].status,
            EngineRunStatus::Queued
        );

        assert_eq!(service.recover_interrupted_scans().unwrap(), 1);
        let mut changed_scope = service.show_case(&case.id).unwrap();
        assert_eq!(
            changed_scope.scan_runs[0].engine_runs[0].status,
            EngineRunStatus::Failed
        );
        assert_eq!(
            changed_scope.scan_runs[0].engine_runs[0]
                .error_code
                .as_deref(),
            Some("preflight_interrupted")
        );
        changed_scope.scope_grants[0].confirmed_at =
            original.scan_run.created_at + Duration::seconds(1);
        fixture
            .storage
            .save_case(&mut changed_scope, "test.scope_reapproved")
            .unwrap();
        let error = service
            .plan_resume(&case.id, &original.scan_run.id)
            .unwrap_err();
        assert!(matches!(error, AppError::NotAvailable(_)));
        let retained = service.show_case(&case.id).unwrap();
        let retained_engine = &retained.scan_runs[0].engine_runs[0];
        assert_eq!(retained_engine.status, EngineRunStatus::Failed);
        assert_eq!(retained_engine.phase, "resume_scope_unavailable");
        assert_eq!(
            retained_engine.error_code.as_deref(),
            Some("resume_scope_unavailable")
        );
        assert!(retained_engine.resume_token.is_some());
    }

    #[test]
    fn one_unavailable_resume_scope_does_not_abort_an_independent_sibling() {
        let fixture = Fixture::new();
        let case = fixture.create();
        let (_, repository_id) = fixture.discovered_asset(&case.id, AssetKind::Repository);
        let (_, account_id) = fixture.discovered_aws_account(&case.id, "111122223333");
        let service = fixture.service();
        service
            .approve_scopes(
                &case.id,
                vec![
                    ScopeApprovalRequest {
                        asset_id: repository_id.clone(),
                        permissions: vec![ScanPermission::LocalArtifactRead],
                        confirmed_by: "Repository owner".into(),
                        expires_at: None,
                        authorization_reference: None,
                        notes: None,
                        external_scope: None,
                    },
                    ScopeApprovalRequest {
                        asset_id: account_id.clone(),
                        permissions: vec![ScanPermission::InventoryRead],
                        confirmed_by: "Account owner".into(),
                        expires_at: None,
                        authorization_reference: None,
                        notes: None,
                        external_scope: None,
                    },
                ],
            )
            .unwrap();
        let original = service
            .plan_scan(
                &case.id,
                ScanPlanRequest {
                    engine_ids: vec!["gitleaks".into(), "cloudquery".into()],
                },
            )
            .unwrap();
        assert_eq!(original.executable.len(), 2);
        assert_eq!(service.recover_interrupted_scans().unwrap(), 1);

        let mut changed_scope = service.show_case(&case.id).unwrap();
        let account_grant = changed_scope
            .scope_grants
            .iter_mut()
            .find(|grant| grant.asset_id == account_id)
            .unwrap();
        account_grant.confirmed_at = original.scan_run.created_at + Duration::seconds(1);
        fixture
            .storage
            .save_case(&mut changed_scope, "test.one_resume_scope_reapproved")
            .unwrap();

        let resumed = service
            .plan_resume(&case.id, &original.scan_run.id)
            .expect("the repository check continues while the cloud check becomes a gap");
        assert_eq!(resumed.executable.len(), 1);
        assert_eq!(resumed.executable[0].manifest.id, "gitleaks");
        assert_eq!(resumed.executable[0].attempt, 2);

        let stored = service.show_case(&case.id).unwrap();
        let repository_check = stored.scan_runs[0]
            .engine_runs
            .iter()
            .find(|engine_run| engine_run.engine_id == "gitleaks")
            .unwrap();
        assert_eq!(repository_check.status, EngineRunStatus::Queued);
        assert_eq!(repository_check.phase, "queued_for_resume");
        let cloud_check = stored.scan_runs[0]
            .engine_runs
            .iter()
            .find(|engine_run| engine_run.engine_id == "cloudquery")
            .unwrap();
        assert_eq!(cloud_check.status, EngineRunStatus::Failed);
        assert_eq!(cloud_check.phase, "resume_scope_unavailable");
        assert_eq!(
            cloud_check.error_code.as_deref(),
            Some("resume_scope_unavailable")
        );
        assert!(cloud_check.resume_token.is_some());
    }

    #[test]
    fn runnable_engines_execute_while_unknown_engines_remain_durable_not_executed_records() {
        let fixture = Fixture::new();
        let case = fixture.create();
        let (_, asset_id) = fixture.discovered_aws_account(&case.id, "111122223333");
        let service = fixture.service();
        service
            .approve_scope(
                &case.id,
                ScopeApprovalRequest {
                    asset_id,
                    permissions: vec![ScanPermission::InventoryRead],
                    confirmed_by: "Owner".into(),
                    expires_at: None,
                    authorization_reference: None,
                    notes: None,
                    external_scope: None,
                },
            )
            .unwrap();
        let plan = service
            .plan_scan(
                &case.id,
                ScanPlanRequest {
                    engine_ids: vec!["steampipe".into(), "missing".into()],
                },
            )
            .unwrap();
        assert_eq!(plan.executable.len(), 1);
        assert_eq!(plan.executable[0].manifest.id, "steampipe");
        assert_eq!(plan.not_executed.len(), 1);
        assert_eq!(plan.not_executed[0].engine_id, "missing");
        let installed = plan
            .scan_run
            .engine_runs
            .iter()
            .find(|run| run.engine_id == "steampipe")
            .unwrap();
        assert_eq!(installed.status, EngineRunStatus::Queued);
        assert!(installed.manifest_schema_version.is_some());
        assert!(installed.repository_url.is_some());
        assert!(installed.command_sha256.is_some());
        assert!(installed.knowledge_input.is_some());
        let missing = plan
            .scan_run
            .engine_runs
            .iter()
            .find(|run| run.engine_id == "missing")
            .unwrap();
        assert_eq!(missing.status, EngineRunStatus::NotExecuted);
        assert_eq!(missing.adapter_version, "unavailable");
        assert!(missing.repository_url.is_none());
    }

    #[test]
    fn aws_only_cloud_images_never_guess_azure_gcp_or_missing_asset_providers() {
        let aws_engine_ids = ["cloudquery", "steampipe", "scoutsuite", "cloudsplaining"];
        for provider in [Some("aws"), Some("azure"), Some("gcp"), None] {
            let fixture = Fixture::new();
            let case = fixture.create();
            let asset_id = if provider == Some("aws") {
                fixture.discovered_aws_account(&case.id, "111122223333").1
            } else {
                let (mut discovered, asset_id) =
                    fixture.discovered_asset(&case.id, AssetKind::CloudAccount);
                discovered.assets[0].provider = provider.map(str::to_owned);
                fixture
                    .storage
                    .save_case(&mut discovered, "test.provider_attributed")
                    .unwrap();
                asset_id
            };
            let service = fixture.service();
            service
                .approve_scope(
                    &case.id,
                    ScopeApprovalRequest {
                        asset_id,
                        permissions: vec![
                            ScanPermission::InventoryRead,
                            ScanPermission::ConfigurationRead,
                        ],
                        confirmed_by: "Owner".into(),
                        expires_at: None,
                        authorization_reference: None,
                        notes: None,
                        external_scope: None,
                    },
                )
                .unwrap();
            let plan = service
                .plan_scan(
                    &case.id,
                    ScanPlanRequest {
                        engine_ids: aws_engine_ids.iter().map(|id| (*id).into()).collect(),
                    },
                )
                .unwrap();

            if provider == Some("aws") {
                assert_eq!(plan.executable.len(), aws_engine_ids.len());
                assert!(plan.not_executed.is_empty());
            } else {
                assert!(plan.executable.is_empty(), "provider {provider:?}");
                assert_eq!(plan.not_executed.len(), aws_engine_ids.len());
                assert!(plan.not_executed.iter().all(|engine| {
                    engine.reason_code == "no_compatible_authorized_assets"
                        && engine.asset_ids.is_empty()
                }));
            }
        }
    }

